66:static pthread_mutex_t g_ready_mtx = PTHREAD_MUTEX_INITIALIZER;
67:static ready_snapshot_t g_snap; /* guarded by g_ready_mtx */
68:static pthread_t g_ready_thread;
69:static int g_ready_thread_started;
