139:int server_write_tier_verify_for_request(const char *token, size_t token_len, int64_t now,
140:                                         server_write_tier_outcome_t *outcome,
141:                                         server_identity_token_claims_t *claims_out)
142:{
143:   server_write_tier_outcome_t local = SERVER_WRITE_TIER_INVALID;
144:   if (!outcome)
145:      outcome = &local;
146:   *outcome = SERVER_WRITE_TIER_INVALID;
147:   if (claims_out)
148:      memset(claims_out, 0, sizeof(*claims_out));
149:
150:   /* Report an absent credential before doing any work, so the ordinary
151:    * read-only caller is never mistaken for a misconfiguration. */
152:   if (!token || token_len == 0 || token[0] == '\0')
153:   {
154:      *outcome = SERVER_WRITE_TIER_ABSENT;
155:      return SERVER_REMOTE_WRITES_OFF;
156:   }
157:
158:   server_write_tier_config_t config;
159:   char bundle[SERVER_MGMT_JWKS_BUNDLE_MAX];
160:   char jwks[SERVER_MGMT_JWKS_BYTES_MAX];
161:   int64_t team = 0;
162:   int tier = SERVER_REMOTE_WRITES_OFF;
163:   if (build_config(&config, jwks, sizeof(jwks), &team, bundle, sizeof(bundle), now, outcome))
164:      tier = server_write_tier_verify(token, token_len, &config, now, outcome, claims_out);
165:   OPENSSL_cleanse(bundle, sizeof(bundle));
166:   OPENSSL_cleanse(jwks, sizeof(jwks));
167:   return tier;
168:}
