2145:    * in-process /v1 dispatch path uses stack-allocated server_conn_t with no
2146:    * evloop registration. */
2147:   if (platform_evloop_create(&ctx->evloop) < 0)
2148:   {
2149:      int saved_errno = errno;
2150:      perror("aimee-server: evloop create");
2151:      errno = saved_errno;
2152:      return -1;
2153:   }
2154:   /* Ensure the config dir (parent of the socket, pid file, and DB1 file)
2155:    * exists before we write the pid file or open DB1. On a fresh AIMEE_HOME
2156:    * (e.g. a deploy not seeded by install.sh) nothing else has created it yet,
2157:    * so without this both server_pid_write and db1_init silently fail and DB1
2158:    * stays unavailable for the whole process lifetime. */
2159:   {
2160:      char cfg_dir[sizeof(ctx->socket_path)];
2161:      snprintf(cfg_dir, sizeof(cfg_dir), "%s", socket_path);
2162:      char *slash = strrchr(cfg_dir, '/');
2163:      if (slash)
2164:      {
2165:         *slash = '\0';
2166:         if (cfg_dir[0])
