53:typedef struct
54:{
55:   dep_state_t db1;
56:   dep_state_t kb;
57:   dep_state_t retrieval;
58:   char failed_boundary[32];
59:   char breaker_state[16];
60:   long long retry_after_ms;
61:   long long last_success_query_ms;
62:   char last_ingest_at[64];
63:   long sampled_at; /* epoch seconds; 0 = never sampled */
64:} ready_snapshot_t;
