194:static void *ready_sampler_main(void *arg)
195:{
196:   (void)arg;
197:   for (;;)
198:   {
199:      server_ready_sample_now();
200:      sleep((unsigned)ready_interval_secs());
201:   }
202:   return NULL;
203:}
