2196:   /* Container cleanup is independent of DB availability. No worker pool exists
2197:    * yet, so a matching container cannot belong to this server generation. */
2198:   int orphan_containers = delegate_backend_docker_remove_orphans();
2199:   if (orphan_containers < 0)
