119:static void json_escape(const char *src, char *dst, size_t cap)
120:{
121:   size_t used = 0;
122:   if (cap == 0)
123:      return;
124:   dst[0] = '\0';
125:   if (!src)
126:      return;
127:   for (const unsigned char *p = (const unsigned char *)src; *p && used + 1 < cap; p++)
128:   {
129:      const char *escape = NULL;
130:      char unicode[7];
131:      if (*p == '"')
132:         escape = "\\\"";
133:      else if (*p == '\\')
134:         escape = "\\\\";
135:      else if (*p < 0x20)
136:      {
137:         snprintf(unicode, sizeof(unicode), "\\u%04x", *p);
138:         escape = unicode;
139:      }
140:      if (escape)
141:      {
142:         size_t n = strlen(escape);
143:         if (used + n >= cap)
144:            break;
145:         memcpy(dst + used, escape, n);
146:         used += n;
147:      }
148:      else
149:         dst[used++] = (char)*p;
150:   }
151:   dst[used] = '\0';
152:}
