291:/* Start the sampler and register the provider. The first sample is taken by the
292: * background thread, NOT here: kb_client_health() is an HTTP call, and doing it
293: * synchronously on the startup path would let an unreachable or slow aimee-kb
294: * delay — or wedge — server startup. That would contradict the whole point of
295: * sampling off the request path. The cost is that readiness reads `unknown`
296: * (503) until the first sample lands, which is the correct fail-closed answer
297: * for a server that genuinely has not checked yet. */
298:void server_ready_register(void)
299:{
300:   if (!g_ready_thread_started)
301:   {
302:      if (pthread_create(&g_ready_thread, NULL, ready_sampler_main, NULL) == 0)
303:      {
304:         pthread_detach(g_ready_thread);
305:         g_ready_thread_started = 1;
306:      }
307:      else
308:      {
309:         /* No sampler means the snapshot can only go stale. Leaving the
310:          * provider registered would then answer `unknown`/503 forever, which
311:          * is the correct fail-closed answer, but say so rather than fail
312:          * silently. */
313:         LOG_ERROR("ready", "readiness sampler thread failed to start");
314:      }
315:   }
316:
317:   server_http_set_ready_provider(ready_provider);
318:}
