218:   long age = (sampled_at > 0) ? (now - sampled_at) : -1;
219:
220:   /* Never sampled, or too old to trust — including a snapshot stamped in the
221:    * future, which means the clock moved and the age is meaningless. Degrade to
222:    * unknown so a wedged sampler cannot keep advertising a stale "ready". */
223:   int stale = (sampled_at <= 0) || (age < 0) || (age > (long)stale_secs);
224:   if (stale)
