142:   if (!n || n > max)
143:      return 0;
144:   for (size_t i = 0; i < n; i++)
145:      if (!((value[i] >= 'A' && value[i] <= 'Z') || (value[i] >= 'a' && value[i] <= 'z') ||
146:            (value[i] >= '0' && value[i] <= '9') || value[i] == '.' || value[i] == '_' ||
147:            value[i] == '-'))
148:         return 0;
149:   return 1;
