2125:{
2126:   memset(ctx, 0, sizeof(*ctx));
2127:   ctx->listen_fd = -1;
2128:   ctx->start_time = time(NULL);
2129:   snprintf(ctx->socket_path, sizeof(ctx->socket_path), "%s", socket_path);
2130:   /* Pid-file check beats connect-probe for liveness on a busy peer. */
2131:   if (server_pid_alive(socket_path))
2132:   {
2133:      LOG_ERROR("server", "another server is already running (pid file)");
2134:      errno = EEXIST;
2135:      return -1;
2136:   }
2137:
2138:   /* The legacy NDJSON RPC listener was removed: aimee-server serves only the
2139:    * /v1 HTTP surface (server_http.c binds its own UDS + optional TCP). No Unix
2140:    * RPC socket is created here, so there is no stale-socket / symlink check and
2141:    * no capability token to load. `fd` stays -1 so the shared error-cleanup paths
2142:    * below remain valid no-ops (close(-1) and unlink of an absent path). */
2143:   int fd = -1;
2144:   /* Event loop retained for shutdown symmetry (platform_evloop_destroy); the
2145:    * in-process /v1 dispatch path uses stack-allocated server_conn_t with no
2146:    * evloop registration. */
2147:   if (platform_evloop_create(&ctx->evloop) < 0)
2148:   {
2149:      int saved_errno = errno;
2150:      perror("aimee-server: evloop create");
2151:      errno = saved_errno;
2152:      return -1;
2153:   }
2154:   /* Ensure the config dir (parent of the socket, pid file, and DB1 file)
2155:    * exists before we write the pid file or open DB1. On a fresh AIMEE_HOME
2156:    * (e.g. a deploy not seeded by install.sh) nothing else has created it yet,
2157:    * so without this both server_pid_write and db1_init silently fail and DB1
2158:    * stays unavailable for the whole process lifetime. */
2159:   {
2160:      char cfg_dir[sizeof(ctx->socket_path)];
2161:      snprintf(cfg_dir, sizeof(cfg_dir), "%s", socket_path);
2162:      char *slash = strrchr(cfg_dir, '/');
2163:      if (slash)
2164:      {
2165:         *slash = '\0';
2166:         if (cfg_dir[0])
2167:            platform_mkdir_p(cfg_dir, 0700);
2168:      }
2169:   }
2170:   /* Record our pid so future server_init calls can detect us deterministically
2171:    * (and `aimee server start/restart` can probe liveness). */
2172:   server_pid_write(socket_path);
2173:   /* Initialize DB1 (aimee-server is DB1's exclusive owner). */
2174:   config_t cfg;
2175:   config_load(&cfg);
2176:   if (db1_init(cfg.db1_path) != 0)
2177:      LOG_WARN("server", "db1_init failed for %s — DB1-backed handlers will be unavailable",
2178:               cfg.db1_path);
2179:   else
2180:   {
2181:      db1_apply_server_pragmas();
2182:      int orphaned = db1_agent_job_cancel_nonterminal_on_restart("orphaned by server restart");
2183:      if (orphaned < 0)
2184:         LOG_WARN("server", "failed to reconcile delegate jobs from the prior process");
2185:      else if (orphaned > 0)
2186:         LOG_INFO("server", "cancelled %d delegate jobs orphaned by the prior process", orphaned);
2187:      if (server_mgmt_status_init() != 0)
2188:         LOG_WARN("server", "management status nonce initialization failed");
2189:      const char *trust_path = getenv("AIMEE_SERVER_MGMT_JWKS_TRUST_BUNDLE");
2190:      if (trust_path && trust_path[0] &&
2191:          server_mgmt_jwks_cache_startup(trust_path, (int64_t)time(NULL),
2192:                                         kb_client_mtls_management_jwks_fetch,
2193:                                         NULL) != SERVER_MGMT_JWKS_CACHE_OK)
2194:         LOG_WARN("server.mgmt", "management JWKS authorization unavailable");
2195:   }
2196:   /* Container cleanup is independent of DB availability. No worker pool exists
2197:    * yet, so a matching container cannot belong to this server generation. */
2198:   int orphan_containers = delegate_backend_docker_remove_orphans();
2199:   if (orphan_containers < 0)
2200:      LOG_WARN("server", "could not reconcile delegate containers from the prior process");
2201:   else if (orphan_containers > 0)
2202:      LOG_INFO("server", "removed %d delegate containers orphaned by the prior process",
2203:               orphan_containers);
2204:   /* Seed personas + role templates so config (not code) is the source of truth. */
2205:   server_seed_config_defaults();
2206:   /* Credential environment variables are first-boot transport only. Seal them
2207:    * before any capability posture checks or workers can consume them. */
2208:   if (server_vault_bootstrap_prepare() < 0)
2209:   {
2210:      LOG_ERROR("server", "delegate credential Vault bootstrap failed");
2211:      close(fd);
2212:      platform_evloop_destroy(&ctx->evloop);
2213:      return -1;
2214:   }
2215:   int compute_threads = aimee_resolve_compute_threads(cfg.compute_threads);
2216:   int session_threads = aimee_resolve_session_threads(cfg.session_threads);
2217:   /* Background (sessionless) delegates run on-demand, gated by the per-model
2218:    * concurrency limiter; this only sets the pathological-fan-out backstop. */
2219:   delegate_ondemand_set_ceiling(aimee_resolve_delegate_max_inflight(cfg.delegate_max_inflight));
2220:   /* Mutex for ctx->conns array (accept inserts; conn_close swap-shrinks). */
2221:   pthread_mutex_init(&ctx->conns_mutex, NULL);
2222:   /* Provider concurrency slots: global active count per agent. */
