2238:      compute_pool_shutdown(&ctx->pool);
2239:      pthread_mutex_destroy(&ctx->conns_mutex);
2240:      close(fd);
2241:      platform_evloop_destroy(&ctx->evloop);
2242:      unlink(socket_path);
2243:      return -1;
2244:   }
