1:/* server_write_tier_db1.c — bridges the pure write-tier policy to the durable
2: * replay store.
3: *
4: * Deliberately a separate translation unit from server_write_tier.c: that file
5: * must stay free of storage dependencies so its decision logic can be unit
6: * tested without a database. This file is the only place the two meet. */
7:
8:#include "server_write_tier_db1.h"
9:
10:#include "server.h" /* SERVER_REMOTE_WRITES_* */
11:#include "server_identity_jti.h"
