32:int server_write_tier_replay_db1(void *ctx, const server_identity_token_claims_t *claims,
33:                                 int64_t now)
34:{
35:   (void)ctx;
36:   if (!claims)
37:      return -1;
38:   const char *tier = tier_text(claims->tier);
39:   if (!tier)
40:      return -1; /* an unrecognized tier is corrupt, not consumable */
41:
42:   server_identity_jti_t record;
43:   memset(&record, 0, sizeof(record));
44:   record.jti = claims->jti;
45:   record.issuer = claims->issuer;
46:   record.kid = claims->kid;
47:   record.audience = claims->audience;
48:   record.subject = claims->subject;
49:   record.team_id = claims->team_id;
50:   record.tier = tier;
51:   record.issued_at = claims->issued_at;
52:   record.expires_at = claims->expires_at;
53:
54:   switch (server_identity_jti_consume(&record, now))
55:   {
56:   case SERVER_IDENTITY_JTI_OK:
57:      return 0; /* previously unseen, now durably recorded */
58:   case SERVER_IDENTITY_JTI_REPLAY:
59:      return 1;
60:   case SERVER_IDENTITY_JTI_SATURATED:
61:   case SERVER_IDENTITY_JTI_STORAGE:
62:   case SERVER_IDENTITY_JTI_INVALID:
63:      break;
64:   }
65:   /* ONLY an explicit OK counts as fresh. Saturation, a storage fault and a
66:    * malformed record all mean the store did not record this jti, so treating
67:    * any of them as "not replayed" would let the same token be presented again
68:    * for as long as the condition lasts. They deny. */
69:   return -1;
70:}
