170:int server_write_tier_consume_for_request(const server_identity_token_claims_t *claims, int64_t now,
171:                                          server_write_tier_outcome_t *outcome)
172:{
173:   server_write_tier_outcome_t local = SERVER_WRITE_TIER_INVALID;
174:   if (!outcome)
175:      outcome = &local;
176:   *outcome = SERVER_WRITE_TIER_INVALID;
177:   if (!claims)
178:      return SERVER_REMOTE_WRITES_OFF;
179:
180:   /* Consumption needs only the replay hook, but it goes through the same
181:    * builder so a server that cannot verify also cannot spend. */
182:   server_write_tier_config_t config;
183:   char bundle[SERVER_MGMT_JWKS_BUNDLE_MAX];
184:   char jwks[SERVER_MGMT_JWKS_BYTES_MAX];
185:   int64_t team = 0;
186:   int tier = SERVER_REMOTE_WRITES_OFF;
187:   if (build_config(&config, jwks, sizeof(jwks), &team, bundle, sizeof(bundle), now, outcome))
188:      tier = server_write_tier_consume(claims, &config, now, outcome);
189:   OPENSSL_cleanse(bundle, sizeof(bundle));
190:   OPENSSL_cleanse(jwks, sizeof(jwks));
