450:   out->valid_until = valid_until;
451:   memcpy(out->jwks, jwks, (size_t)jn + 1);
452:   out->jwks_len = (size_t)jn;
453:   memcpy(out->manifest_sha256, computed_manifest, 32);
454:   memcpy(out->trust_bundle_sha256, trust.bundle_digest, 32);
455:   ok = 1;
456:done:
457:   free(jwk);
458:   cJSON_Delete(root);
459:   OPENSSL_cleanse(&trust, sizeof(trust));
460:   OPENSSL_cleanse(signature, sizeof(signature));
461:   if (!ok)
462:   {
463:      memset(out, 0, sizeof(*out));
464:      return SERVER_MGMT_JWKS_CACHE_INVALID;
465:   }
466:   if (now < valid_from || now >= valid_until)
467:   {
468:      memset(out, 0, sizeof(*out));
469:      return SERVER_MGMT_JWKS_CACHE_STALE;
470:   }
471:   return SERVER_MGMT_JWKS_CACHE_OK;
472:}
