474:server_mgmt_jwks_cache_result_t server_mgmt_jwks_cache_install(const char *trust_bundle,
475:                                                               size_t trust_bundle_len,
476:                                                               const char *envelope,
477:                                                               size_t envelope_len, int64_t now)
478:{
479:   server_mgmt_jwks_cache_record_t record;
480:   server_mgmt_jwks_cache_result_t valid = server_mgmt_jwks_envelope_validate(
481:       trust_bundle, trust_bundle_len, envelope, envelope_len, now, &record);
482:   if (valid != SERVER_MGMT_JWKS_CACHE_OK)
483:      return valid;
484:   sqlite3 *db = db1_conn();
485:   if (!db || db1_txn_begin_nowait(db, "BEGIN IMMEDIATE") != 0)
486:      return SERVER_MGMT_JWKS_CACHE_STORAGE;
487:   sqlite3_stmt *q = NULL;
488:   server_mgmt_jwks_cache_result_t result = SERVER_MGMT_JWKS_CACHE_STORAGE;
489:   if (sqlite3_prepare_v2(db,
490:                          "SELECT envelope_sha256,trust_bundle_sha256 FROM "
491:                          "server_management_jwks_cache WHERE singleton=1",
492:                          -1, &q, NULL) != SQLITE_OK)
493:      goto rollback;
494:   int step = sqlite3_step(q);
495:   if (step == SQLITE_ROW)
496:   {
497:      const void *envelope_digest = sqlite3_column_blob(q, 0);
498:      const void *bundle_digest = sqlite3_column_blob(q, 1);
499:      int same = envelope_digest && bundle_digest && sqlite3_column_bytes(q, 0) == 32 &&
500:                 sqlite3_column_bytes(q, 1) == 32 &&
501:                 !CRYPTO_memcmp(envelope_digest, record.envelope_sha256, 32) &&
502:                 !CRYPTO_memcmp(bundle_digest, record.trust_bundle_sha256, 32);
503:      sqlite3_finalize(q);
504:      q = NULL;
505:      if (!same)
506:      {
507:         result = SERVER_MGMT_JWKS_CACHE_CONFLICT;
508:         goto rollback;
509:      }
510:      result = SERVER_MGMT_JWKS_CACHE_OK;
511:      return db1_txn_commit_or_rollback(db) == 0 ? result : SERVER_MGMT_JWKS_CACHE_STORAGE;
512:   }
513:   sqlite3_finalize(q);
514:   q = NULL;
515:   if (step != SQLITE_DONE ||
516:       sqlite3_prepare_v2(db,
517:                          "INSERT INTO server_management_jwks_cache(singleton,generation,"
518:                          "valid_from,valid_until,jwks_bytes,envelope_bytes,envelope_sha256,"
519:                          "manifest_sha256,trust_bundle_sha256,fetched_at)"
520:                          " VALUES(1,1,?1,?2,?3,?4,?5,?6,?7,?8)",
521:                          -1, &q, NULL) != SQLITE_OK ||
522:       sqlite3_bind_int64(q, 1, record.valid_from) != SQLITE_OK ||
523:       sqlite3_bind_int64(q, 2, record.valid_until) != SQLITE_OK ||
524:       sqlite3_bind_blob(q, 3, record.jwks, (int)record.jwks_len, SQLITE_TRANSIENT) != SQLITE_OK ||
525:       sqlite3_bind_blob(q, 4, envelope, (int)envelope_len, SQLITE_TRANSIENT) != SQLITE_OK ||
526:       sqlite3_bind_blob(q, 5, record.envelope_sha256, 32, SQLITE_TRANSIENT) != SQLITE_OK ||
527:       sqlite3_bind_blob(q, 6, record.manifest_sha256, 32, SQLITE_TRANSIENT) != SQLITE_OK ||
528:       sqlite3_bind_blob(q, 7, record.trust_bundle_sha256, 32, SQLITE_TRANSIENT) != SQLITE_OK ||
529:       sqlite3_bind_int64(q, 8, now) != SQLITE_OK || sqlite3_step(q) != SQLITE_DONE)
530:      goto rollback;
531:   sqlite3_finalize(q);
532:   return db1_txn_commit_or_rollback(db) == 0 ? SERVER_MGMT_JWKS_CACHE_OK
533:                                              : SERVER_MGMT_JWKS_CACHE_STORAGE;
534:rollback:
535:   sqlite3_finalize(q);
536:   db1_txn_end(db, "ROLLBACK");
537:   return result;
538:}
