540:server_mgmt_jwks_cache_result_t server_mgmt_jwks_cache_load(const char *trust_bundle,
541:                                                            size_t trust_bundle_len, int64_t now,
542:                                                            char *jwks_out, size_t jwks_cap,
543:                                                            size_t *jwks_len)
544:{
545:   if (jwks_out && jwks_cap)
546:      memset(jwks_out, 0, jwks_cap);
547:   if (jwks_len)
548:      *jwks_len = 0;
549:   if (!jwks_out || !jwks_cap || !jwks_len)
550:      return SERVER_MGMT_JWKS_CACHE_INVALID;
551:   sqlite3 *db = db1_conn();
552:   sqlite3_stmt *q = NULL;
553:   if (!db || sqlite3_prepare_v2(db,
554:                                 "SELECT envelope_bytes,valid_from,valid_until,envelope_sha256,"
555:                                 "manifest_sha256,trust_bundle_sha256 FROM "
556:                                 "server_management_jwks_cache WHERE singleton=1",
557:                                 -1, &q, NULL) != SQLITE_OK)
558:      return SERVER_MGMT_JWKS_CACHE_STORAGE;
559:   int step = sqlite3_step(q);
560:   if (step == SQLITE_DONE)
561:   {
562:      sqlite3_finalize(q);
563:      return SERVER_MGMT_JWKS_CACHE_MISSING;
564:   }
565:   if (step != SQLITE_ROW)
566:   {
567:      sqlite3_finalize(q);
568:      return SERVER_MGMT_JWKS_CACHE_STORAGE;
569:   }
570:   const void *raw = sqlite3_column_blob(q, 0);
571:   int raw_n = sqlite3_column_bytes(q, 0);
572:   char envelope[SERVER_MGMT_JWKS_ENVELOPE_MAX];
573:   if (!raw || raw_n < 1 || raw_n >= (int)sizeof(envelope))
574:   {
575:      sqlite3_finalize(q);
576:      return SERVER_MGMT_JWKS_CACHE_INVALID;
577:   }
578:   memcpy(envelope, raw, (size_t)raw_n);
579:   envelope[raw_n] = '\0';
580:   int64_t stored_from = sqlite3_column_int64(q, 1), stored_until = sqlite3_column_int64(q, 2);
581:   unsigned char digests[3][32];
582:   for (int i = 0; i < 3; ++i)
583:   {
584:      const void *d = sqlite3_column_blob(q, 3 + i);
585:      if (!d || sqlite3_column_bytes(q, 3 + i) != 32)
586:      {
587:         sqlite3_finalize(q);
588:         return SERVER_MGMT_JWKS_CACHE_INVALID;
589:      }
590:      memcpy(digests[i], d, 32);
591:   }
592:   sqlite3_finalize(q);
593:   server_mgmt_jwks_cache_record_t record;
594:   server_mgmt_jwks_cache_result_t result = server_mgmt_jwks_envelope_validate(
595:       trust_bundle, trust_bundle_len, envelope, (size_t)raw_n, now, &record);
596:   if (result != SERVER_MGMT_JWKS_CACHE_OK || record.valid_from != stored_from ||
597:       record.valid_until != stored_until ||
598:       CRYPTO_memcmp(record.envelope_sha256, digests[0], 32) ||
599:       CRYPTO_memcmp(record.manifest_sha256, digests[1], 32) ||
600:       CRYPTO_memcmp(record.trust_bundle_sha256, digests[2], 32) || record.jwks_len + 1 > jwks_cap)
601:      return result == SERVER_MGMT_JWKS_CACHE_STALE ? result : SERVER_MGMT_JWKS_CACHE_INVALID;
602:   memcpy(jwks_out, record.jwks, record.jwks_len + 1);
603:   *jwks_len = record.jwks_len;
604:   return SERVER_MGMT_JWKS_CACHE_OK;
605:}
