607:server_mgmt_jwks_cache_result_t server_mgmt_jwks_cache_current_generation(const char *trust_bundle,
608:                                                                          size_t trust_bundle_len,
609:                                                                          int64_t now,
610:                                                                          int64_t *generation)
611:{
612:   if (generation)
613:      *generation = 0;
614:   if (!generation)
615:      return SERVER_MGMT_JWKS_CACHE_INVALID;
616:   char jwks[SERVER_MGMT_JWKS_BYTES_MAX];
617:   size_t jwks_len = 0;
618:   server_mgmt_jwks_cache_result_t result = server_mgmt_jwks_cache_load(
619:       trust_bundle, trust_bundle_len, now, jwks, sizeof(jwks), &jwks_len);
620:   OPENSSL_cleanse(jwks, sizeof(jwks));
621:   if (result != SERVER_MGMT_JWKS_CACHE_OK)
622:      return result;
623:   sqlite3 *db = db1_conn();
624:   sqlite3_stmt *q = NULL;
625:   if (!db || sqlite3_prepare_v2(db,
626:                                 "SELECT generation FROM server_management_jwks_cache "
627:                                 "WHERE singleton=1",
628:                                 -1, &q, NULL) != SQLITE_OK)
629:      return SERVER_MGMT_JWKS_CACHE_STORAGE;
630:   int step = sqlite3_step(q);
631:   int64_t found = step == SQLITE_ROW ? sqlite3_column_int64(q, 0) : 0;
632:   int tail = step == SQLITE_ROW ? sqlite3_step(q) : step;
633:   sqlite3_finalize(q);
634:   if (found < 1 || tail != SQLITE_DONE)
635:      return step == SQLITE_DONE ? SERVER_MGMT_JWKS_CACHE_MISSING : SERVER_MGMT_JWKS_CACHE_INVALID;
636:   *generation = found;
637:   return SERVER_MGMT_JWKS_CACHE_OK;
638:}
