644:server_mgmt_jwks_cache_result_t server_mgmt_jwks_cache_refresh(const char *trust_bundle,
645:                                                               size_t trust_bundle_len, int64_t now,
646:                                                               server_mgmt_jwks_fetch_fn fetch,
647:                                                               void *fetch_ctx)
648:{
649:   if (!fetch)
650:      return SERVER_MGMT_JWKS_CACHE_INVALID;
651:   pthread_mutex_lock(&refresh_lock);
652:   if (refresh_active)
653:   {
654:      while (refresh_active)
655:         pthread_cond_wait(&refresh_condition, &refresh_lock);
656:      pthread_mutex_unlock(&refresh_lock);
657:      char jwks[SERVER_MGMT_JWKS_BYTES_MAX];
658:      size_t jwks_n = 0;
659:      return server_mgmt_jwks_cache_load(trust_bundle, trust_bundle_len, now, jwks, sizeof(jwks),
660:                                         &jwks_n);
661:   }
662:   refresh_active = 1;
663:   pthread_mutex_unlock(&refresh_lock);
664:
665:   char envelope[SERVER_MGMT_JWKS_ENVELOPE_MAX] = {0};
666:   size_t envelope_n = 0;
667:   server_mgmt_jwks_cache_result_t result = SERVER_MGMT_JWKS_CACHE_STORAGE;
668:   if (fetch(fetch_ctx, envelope, sizeof(envelope), &envelope_n) == 0 && envelope_n > 0 &&
669:       envelope_n < sizeof(envelope) && envelope[envelope_n] == '\0')
670:      result =
671:          server_mgmt_jwks_cache_install(trust_bundle, trust_bundle_len, envelope, envelope_n, now);
672:   OPENSSL_cleanse(envelope, sizeof(envelope));
673:
674:   pthread_mutex_lock(&refresh_lock);
675:   refresh_active = 0;
676:   pthread_cond_broadcast(&refresh_condition);
677:   pthread_mutex_unlock(&refresh_lock);
678:   return result;
679:}
