41:int main(void)
42:{
43:   char resp[2048];
44:   server_ready_diagnostics_t ok = {1, "", "closed", 0, 999000, "2026-07-30T00:00:00Z"};
45:   server_ready_diagnostics_t failed = {0,    "kb_breaker", "open",
46:                                        1200, 998000,       "2026-07-30T00:00:00Z"};
47:
48:   /* Never sampled ⇒ unknown, not ready, and a null age rather than a
49:    * fabricated one. An unsampled server must never read as ready. */
50:   {
51:      int st = server_ready_render(-1, -1, NULL, 0, NOW, 60, resp, sizeof(resp));
52:      assert(st == 503);
53:      assert(strstr(resp, "\"ready\":false"));
54:      assert(strstr(resp, "\"status\":\"unknown\""));
55:      assert(strstr(resp, "\"sampled_at\":null"));
56:      assert(strstr(resp, "\"age_seconds\":null"));
57:   }
58:   {
59:      int st = server_ready_render(1, 1, &failed, NOW - 5, NOW, 60, resp, sizeof(resp));
60:      assert(st == 503);
61:      assert(strstr(resp, "\"status\":\"degraded\""));
62:      assert(strstr(resp, "\"kb\":\"ok\""));
63:      assert(strstr(resp, "\"retrieval\":\"fail\""));
64:      assert(strstr(resp, "\"failed_boundary\":\"kb_breaker\""));
65:   }
66:
67:   /* Dependency text cannot break the JSON diagnostics object. */
68:   {
69:      server_ready_diagnostics_t escaped = ok;
70:      escaped.last_ingest_at = "quote\" slash\\ newline\n";
71:      int st = server_ready_render(1, 1, &escaped, NOW - 5, NOW, 60, resp, sizeof(resp));
72:      assert(st == 200);
73:      assert(strstr(resp, "quote\\\" slash\\\\ newline\\u000a"));
74:   }
75:
76:   /* Fresh sample, everything ok ⇒ ready. */
77:   {
78:      int st = server_ready_render(1, 1, &ok, NOW - 5, NOW, 60, resp, sizeof(resp));
79:      assert(st == 200);
80:      assert(strstr(resp, "\"ready\":true"));
81:      assert(strstr(resp, "\"status\":\"ok\""));
82:      assert(strstr(resp, "\"db1\":\"ok\""));
83:      assert(strstr(resp, "\"kb\":\"ok\""));
84:      assert(strstr(resp, "\"retrieval\":\"ok\""));
85:      assert(strstr(resp, "\"last_success_query_ms\":999000"));
86:      assert(strstr(resp, "\"age_seconds\":5"));
87:   }
88:
89:   /* A fresh snapshot with missing diagnostics fails closed with valid,
90:    * deterministic JSON rather than exposing uninitialized stack text. */
91:   {
92:      int st = server_ready_render(1, 1, NULL, NOW - 5, NOW, 60, resp, sizeof(resp));
93:      assert(st == 503);
94:      assert(strstr(resp, "\"retrieval\":\"unknown\""));
95:      assert(strstr(resp, "\"failed_boundary\":\"\""));
96:      assert(strstr(resp, "\"breaker_state\":\"\""));
97:      assert(strstr(resp, "\"last_ingest_at\":\"\""));
98:   }
99:
100:   /* One dependency down ⇒ not ready, degraded, and the failing dependency is
101:    * named rather than hidden behind a roll-up. */
102:   {
103:      int st = server_ready_render(1, 0, &failed, NOW - 5, NOW, 60, resp, sizeof(resp));
104:      assert(st == 503);
105:      assert(strstr(resp, "\"ready\":false"));
106:      assert(strstr(resp, "\"status\":\"degraded\""));
107:      assert(strstr(resp, "\"db1\":\"ok\""));
108:      assert(strstr(resp, "\"kb\":\"fail\""));
