106:static const char *dep_name(dep_state_t s)
107:{
108:   switch (s)
109:   {
110:   case DEP_OK:
111:      return "ok";
112:   case DEP_FAIL:
113:      return "fail";
114:   default:
115:      return "unknown";
116:   }
117:}
