139:int server_write_tier_verify_for_request(const char *token, size_t token_len, int64_t now,
140:                                         server_write_tier_outcome_t *outcome,
141:                                         server_identity_token_claims_t *claims_out)
142:{
143:   server_write_tier_outcome_t local = SERVER_WRITE_TIER_INVALID;
144:   if (!outcome)
145:      outcome = &local;
146:   *outcome = SERVER_WRITE_TIER_INVALID;
147:   if (claims_out)
148:      memset(claims_out, 0, sizeof(*claims_out));
149:
150:   /* Report an absent credential before doing any work, so the ordinary
151:    * read-only caller is never mistaken for a misconfiguration. */
152:   if (!token || token_len == 0 || token[0] == '\0')
153:   {
154:      *outcome = SERVER_WRITE_TIER_ABSENT;
155:      return SERVER_REMOTE_WRITES_OFF;
156:   }
157:
158:   server_write_tier_config_t config;
159:   char bundle[SERVER_MGMT_JWKS_BUNDLE_MAX];
160:   char jwks[SERVER_MGMT_JWKS_BYTES_MAX];
161:   int64_t team = 0;
162:   int tier = SERVER_REMOTE_WRITES_OFF;
163:   if (build_config(&config, jwks, sizeof(jwks), &team, bundle, sizeof(bundle), now, outcome))
164:      tier = server_write_tier_verify(token, token_len, &config, now, outcome, claims_out);
165:   OPENSSL_cleanse(bundle, sizeof(bundle));
166:   OPENSSL_cleanse(jwks, sizeof(jwks));
167:   return tier;
168:}
169:
170:int server_write_tier_consume_for_request(const server_identity_token_claims_t *claims, int64_t now,
171:                                          server_write_tier_outcome_t *outcome)
172:{
173:   server_write_tier_outcome_t local = SERVER_WRITE_TIER_INVALID;
174:   if (!outcome)
175:      outcome = &local;
176:   *outcome = SERVER_WRITE_TIER_INVALID;
177:   if (!claims)
178:      return SERVER_REMOTE_WRITES_OFF;
179:
180:   /* Consumption needs only the replay hook, but it goes through the same
181:    * builder so a server that cannot verify also cannot spend. */
182:   server_write_tier_config_t config;
183:   char bundle[SERVER_MGMT_JWKS_BUNDLE_MAX];
184:   char jwks[SERVER_MGMT_JWKS_BYTES_MAX];
185:   int64_t team = 0;
186:   int tier = SERVER_REMOTE_WRITES_OFF;
187:   if (build_config(&config, jwks, sizeof(jwks), &team, bundle, sizeof(bundle), now, outcome))
188:      tier = server_write_tier_consume(claims, &config, now, outcome);
189:   OPENSSL_cleanse(bundle, sizeof(bundle));
190:   OPENSSL_cleanse(jwks, sizeof(jwks));
191:   return tier;
192:}

