31:int server_http_management_action_begin(void)
32:{
33:   pthread_mutex_lock(&g_management_action_lock);
34:   int ok = !g_management_action_stopping;
35:   if (ok)
36:      g_management_action_active++;
37:   pthread_mutex_unlock(&g_management_action_lock);
38:   return ok ? 0 : -1;
