49:void server_http_management_action_end(void)
50:{
51:   pthread_mutex_lock(&g_management_action_lock);
52:   if (g_management_action_active)
53:      g_management_action_active--;
54:   if (!g_management_action_active)
55:      pthread_cond_broadcast(&g_management_action_idle);
56:   pthread_mutex_unlock(&g_management_action_lock);
