162:static int management_absolute_path(const char *path)
163:{
164:   size_t length = path ? strnlen(path, SERVER_HTTP_MGMT_PATH_MAX) : 0;
165:   if (length < 2 || length >= SERVER_HTTP_MGMT_PATH_MAX || path[0] != '/')
166:      return 0;
167:   const char *part = path + 1;
168:   while (*part)
169:   {
170:      const char *slash = strchr(part, '/');
171:      size_t n = slash ? (size_t)(slash - part) : strlen(part);
172:      if (!n || n > 255 || (n == 1 && part[0] == '.') ||
173:          (n == 2 && part[0] == '.' && part[1] == '.'))
174:         return 0;
175:      if (!slash)
176:         return 1;
177:      part = slash + 1;
178:   }
179:   return 0;
180:}
