182:int server_http_management_bind_addr(const char *text, uint32_t *out)
183:{
184:   struct in_addr addr;
185:   if (out)
186:      *out = 0;
187:   if (!text || !out || strnlen(text, 16) >= 16 || inet_pton(AF_INET, text, &addr) != 1)
188:      return -1;
189:   /* inet_ntop supplies the one canonical spelling accepted by the environment
190:    * packet (no octal, leading-zero, hostname, or alternate textual address). */
191:   char canonical[INET_ADDRSTRLEN];
192:   if (!inet_ntop(AF_INET, &addr, canonical, sizeof(canonical)) || strcmp(canonical, text))
193:      return -1;
194:   uint32_t host = ntohl(addr.s_addr);
195:   if (host == INADDR_ANY || host == INADDR_BROADCAST || (host & 0xf0000000U) == 0xe0000000U ||
196:       (host & 0xffff0000U) == 0xa9fe0000U)
197:      return -1;
198:   *out = addr.s_addr;
199:   return 0;
200:}
