1:/* test_server_ready.c: the readiness decision behind GET /v1/ready.
2: *
3: * Exercises server_ready_render() — the pure snapshot→(body,status) function —
4: * by passing an explicit clock, so staleness and roll-up behavior are tested
5: * deterministically rather than by sleeping past a real sampling interval.
6: *
7: * The sampler's own I/O (kb_client_health / db1_is_initialized) is stubbed:
8: * this suite is about the decision, not about reaching the dependencies. */
9:#include "server_http.h"
10:#include "kb_client.h"
11:#include <assert.h>
12:#include <stdio.h>
13:#include <string.h>
14:
15:/* --- stubs for the sampler's dependency closure (link-only) --- */
16:int db1_is_initialized(void)
17:{
18:   return 1;
19:}
20:
21:int kb_client_health(kb_health_t *out)
22:{
23:   if (out)
24:      memset(out, 0, sizeof(*out));
25:   return -1;
26:}
