126:static int b64_value(unsigned char c)
127:{
128:   if (c >= 'A' && c <= 'Z')
129:      return c - 'A';
130:   if (c >= 'a' && c <= 'z')
131:      return c - 'a' + 26;
132:   if (c >= '0' && c <= '9')
133:      return c - '0' + 52;
134:   return c == '-' ? 62 : (c == '_' ? 63 : -1);
135:}
