223:static int derive_kid(const unsigned char modulus[384], char out[65])
224:{
225:   static const char domain[] = "aimee.p5.token.public.v1\n";
226:   static const unsigned char exponent[] = {1, 0, 1};
227:   unsigned char ml[4], el[4], digest[32];
228:   put_u32be(ml, 384);
229:   put_u32be(el, 3);
230:   EVP_MD_CTX *md = EVP_MD_CTX_new();
231:   unsigned int n = 0;
232:   int ok = md && EVP_DigestInit_ex(md, EVP_sha256(), NULL) == 1 &&
233:            EVP_DigestUpdate(md, domain, sizeof(domain) - 1) == 1 &&
234:            EVP_DigestUpdate(md, ml, sizeof(ml)) == 1 && EVP_DigestUpdate(md, modulus, 384) == 1 &&
235:            EVP_DigestUpdate(md, el, sizeof(el)) == 1 &&
236:            EVP_DigestUpdate(md, exponent, sizeof(exponent)) == 1 &&
237:            EVP_DigestFinal_ex(md, digest, &n) == 1 && n == 32;
238:   EVP_MD_CTX_free(md);
239:   if (!ok)
240:      return -1;
241:   memcpy(out, "p5-token-v1-", 12);
242:   hex_encode(digest, 16, out + 12);
243:   return 0;
244:}
